mapper.insert:
insert into todo_instance(todo_no,template_id,template_version_id,template_code,title,business_type,business_id,business_no,business_stage,owner_id,owner_dept_id,status,priority,sla_status,created_at,due_at,previous_todo_id,root_todo_id,trigger_idempotency_key,dod_snapshot_json,version,create_by)
select concat('REGEN-',#{actionId},'-',todo_id),template_id,template_version_id,template_code,title,business_type,business_id,business_no,business_stage,owner_id,owner_dept_id,'CREATED',priority,'NORMAL',sysdate(),due_at,todo_id,coalesce(root_todo_id,todo_id),concat('REGENERATE:',#{actionId}),dod_snapshot_json,0,#{operator}
from todo_instance where todo_id=#{sourceTodoId}
